function get_vs_effect_desc(id,mode)
for i=1,#vs_effect do
  if vs_effect[i][1] == id then
    if mode ~= 1 then
      if vs_effect[i][5] == 1 then
        ban[1][vs_effect[i][6]] = ban[1][vs_effect[i][6]]*(1+vs_effect[i][7]*0.01)
      elseif vs_effect[i][5] == 10 then
        ban[2][vs_effect[i][6]] = vs_effect[i][7]
      elseif vs_effect[i][5] == 4 then
        ban[3][vs_effect[i][6]] = vs_effect[i][7]
      else
        table.insert(ban[4],vs_effect[i][3])
      end
    end
    return {vs_effect[i][3],vs_effect[i][4]}
  end
end
end

function get_vs_effect(id)
local tmp = {}
local index = -1
for i=1,#vs_group do
  if vs_group[i][1] == id*100+1 then
    index = i-1
    break
  end
end
if index == -1 then print("无效场地效果ID"..id)
else
  for i=1,10 do
    tmp[i] = {
    ["name"]=vs_group[index+i][2],
    ["a"]=get_vs_effect_desc(vs_group[index+i][3])[1],
    ["type"]=get_vs_effect_desc(vs_group[index+i][3],1)[2],
    ["b"]=get_vs_effect_desc(vs_group[index+i][4])[1]
    }
  end
end
return tmp
end

function get_card(id)
if id < 100000 then
for i=1,#card do
  if card[i][1] == id then
    return card[i][2]
  end
end
else return "" end
end

function get_vs_info(id)
local tmp = {}
for i=1,#st do
  if st[i][1] == id then
    effects = get_vs_effect(st[i][6])
    tmp["name"] = st[i][2]
    tmp["card_name"] = get_card(st[i][10])
    tmp["card_id"] = st[i][10]
    tmp["char"] = st[i][12]
    info = tmp
    op()
    for j=3,5 do
      gauge = {}
      get_enemy(st[i][j])
    end
    break
  end
end
n('{{板块|内容结束}}')
    
io.open("复灵"..id..".txt","w"):write(output)
return tmp
end

