function get_ban_effect(mode)
local tmp = {}
if mode == 1 then
  local f_name = {
  "heal",
  "speed_up",
  "yang_atk_up",
  "yang_def_up",
  "yin_atk_up",
  "yin_def_up",
  "hit_up",
  "dodge_up",
  }
  for i=1,8 do
    if ban[1][i] > 1 then
      table.insert(tmp,'[[File:skill icon '..f_name[i]..'.png|50px]]<br>+'..string.format("%.0f",(ban[1][i]-1)*100) ..'%')
    end
  end
  return table.concat(tmp,"||")
end
if mode == 2 then
  for i=1,11 do
    if ban[2][i] ~= nil then
      if ban[2][i] < -80 then
        table.insert(tmp,'[[File:Bullet Type Icon '..string.format("%02d",i)..'.png|50px]]<br>\'\'\'<font color=#aa0000>'..ban[2][i]..'%</font>\'\'\'')
      else
        table.insert(tmp,'[[File:Bullet Type Icon '..string.format("%02d",i)..'.png|50px]]<br>'..ban[2][i] ..'%')
      end
    end
  end
  return table.concat(tmp,"||")
end
if mode == 3 then
local type={"防御","支援","回复","干扰","攻击","技巧","速攻","破坏"}
  for i=1,8 do
    if ban[3][i] ~= nil then
      if ban[3][i] < -80 then
        table.insert(tmp,'[[File:式图标 '..type[i]..'.png|50px]]<br>\'\'\'<font color=#aa0000>'..ban[3][i]..'%</font>\'\'\'')
      else
        table.insert(tmp,'[[File:式图标 '..type[i]..'.png|50px]]<br>'..ban[3][i] ..'%')
      end
    end
  end
  return table.concat(tmp,"||")
end
end

