function clone(object)
    local lookup_table = {}
    local function _copy(object)
        if type(object) ~= "table" then
            return object
        elseif lookup_table[object] then
            return lookup_table[object]
        end
        local new_table = {}
        lookup_table[object] = new_table
        for key, value in pairs(object) do
            new_table[_copy(key)] = _copy(value)
        end
        return setmetatable(new_table, getmetatable(object))
    end
    return _copy(object)
end

function get_enemy(id,mode,r)
if id > 0 then
for i=1,#td do
  if td[i][1] == id then
    local tmp = td[i]
    if #tmp == 43 or #tmp == 49 then
      for i=1,6 do
        tmp[i+4] = tmp[i+4].."~<br>"..tmp[11]
        table.remove(tmp,11)
      end
      table.insert(tmp,14,0)
    end
    table.insert(gauge,clone(tmp))
    if mode ~= 1 then
      -- print(tmp)
      if tmp[#tmp-13] ~= 0 then
        if tmp[#tmp-13][2] ~= 0 then get_enemy(tmp[#tmp-13][2],1) end
        if tmp[#tmp-13][3] ~= 0 then get_enemy(tmp[#tmp-13][3],1) end
      end
    op3(tmp)
    end
    break
  end
end
end
end

