  for i=1,#items do
    if items[i][1] == n2 then return string.gsub(string.gsub(items[i][2],"%[","-"),"%]","") end
  end
end
end

function get_drop_item(floor)
local tmp = {}
for i=1,#drops do
  if drops[i][2]%1000 == floor then
    -- print(get_item_name(drops[i][3],drops[i][4]))
    table.insert(tmp,'[[File:'..get_item_name(drops[i][3],drops[i][4])..'.png|70px]]<br>*'..drops[i][5])
  end
end
return table.concat(tmp,"||")
end

