function get_bullet_effect(input)
local addon = input[1]
local Buff = input[2]
local lv = input[3]
local cp = input[4]
local yinyang = input[5]
local yy = {[0]="阴攻",[1]="阳攻"}
local tmp = {'[[file:面板 '..yy[yinyang]..'.png|15px]]'..string.format("%.0f",math.ceil(cp))}
for i=1,18 do
  if addon[i] ~= nil and addon[i] > 0 then
    table.insert(tmp,'[[File:段落 '..tag[i]..'.png|15px]]'..addon[i])
    if i == 18 then table.insert(tmp,"'''<font color=#ff0000>对擦弹目标造成"..addon[i].."%伤害</font>'''") end
  end
end
local name = ""
for i=1,#Buff do
  if Buff[i] > 0 then
    -- 对象 持续回合 类型 子类型 效果量，范围4~8
    local bid = Buff[i]*1
    if buff[bid][6] == 1 then
      name = "效果 "..buff_t[buff[bid][7]][1].." 上升"
    end
    if buff[bid][6] == 2 then
      name = "效果 "..buff_t[buff[bid][7]][1].." 下降"
    end
    if buff[bid][6] == 6 then
      name = "段落 "..bs[buff[bid][7]]
    end
    if buff[bid][6] == 7 and buff[bid][7] == 1 then
      name = "段落 冲击"
    end
    if buff[bid][6] == 7 and buff[bid][7] == 2 then
      name = "段落 粘着"
    end
    table.insert(tmp,'[[File:'..name..'.png|15px]]'..buff[bid][8].."("..buff[bid][5].."T) "..lv[i].."%")
  end
end
return table.concat(tmp,"<br>")
end




function get_ability(id)
for i=1,#abl do
  if abl[i][1] == id then
    local tmp = ""
    for j=2,6 do
      if abl[i][j] ~= "" then tmp = tmp..abl[i][j].."\n" end
    end
    return skill_transform(tmp)
  end
end
return "无"
end

