function f_buff(n1,n2)
if n1 < 13 then
  return buff_t[n1][1]
elseif n1 == 14 then
  return elements_b[n2][1].."伤害"
end
end

function get_field(id)
gg.clearResults()
gg.searchNumber(id..";-1~40000;"..id.."::9",4,false,gg.SIGN_EQUAL,base.field,base.field+1000)
if gg.getResultCount() == 0 then return "无效" end
-- A=gg.getResults(100)[1].address
gi(base.field)
gv2(32,16,17,A,1)
A = gg.getResults(100)[1].value
if A < 0 then A = A + 2147483648*2 end
-- A = gg.getResults(100)[1].value
-- field_color=gn(4,32,A)
field_skill_a="己方全体"..f_buff(gn(4,36,A),gn(4,40,A)).."<color=#FF6600>上升</color>"..gn(4,160,A).."%"
field_skill_b="敌方全体"..f_buff(gn(4,44,A),gn(4,48,A)).."<color=#0066FF>下降</color>"..gn(4,280,A).."%"
field_destruction_skill = skt({gn(4,292,A),gn(4,296,A),2,gn(4,300,A),gn(4,304,A)},nil,nil,nil,1)
return field_skill_a..",\\n"..field_skill_b
end

function sd(input)
if input[eft[2]] == nil then
  t = "无效"
else
  t = input[eft[2]][1]
end
end

function skt(effect,i,m2,m) -- skill text
