if buff_type[effect[1]][2] == "buff" then
  if effect[2] > 100 then
    t1 = math.floor(effect[2]/100)
    t2 = effect[2]%100
    t1 = buff_t[t1][1]
    t2 = buff_t[t2][1]
    if effect[1] == 1 then return targets[effect[3]][1].."<color=#CCAA00>"..t1.."+"..t2.."</color><color=#FF6600>上升</color>"..effect[5].."等级 ("..effect[4].."回合)" end
