function pd(p) -- P点显示
return string.format("%.2f",p*0.01)
end

function skill_transform(input)
local tmp = clone(input)
if type(tmp) == "table" then
for i=1,#tmp do
tmp[i] = skt(tmp[i])
tmp[i] = s_icon..tmp[i]
end
tmp = table.concat(tmp,"\n")
end
-- print(tmp)
local tmp = string.gsub(tmp,"\n","<br>")
local tmp = string.gsub(tmp,"color=","font color=")
local tmp = string.gsub(tmp,"/color","/font")
return tmp
end

function equal(input) -- 比较所有数值是否相等
local v = true
local tmp = clone(input)
for i=1,#tmp do -- 将表转为字符串
  if type(tmp[i]) == "table" then -- 是表类型？
    for j=1,#tmp[i] do
      if type(tmp[i][j]) == "table" then -- 再确认一次
        tmp[i][j] = table.concat(tmp[i][j],"|")
      end
    end
    tmp[i] = table.concat(tmp[i],"|")
  end
end
for i=1,#tmp-1 do
  if tmp[i] ~= tmp[i+1] then v = false break end
end
return v
end

function table.max(input)
local tmp = 0
for i=1,#input do
  if input[i] > tmp then tmp = input[i] end
end
return tmp
end

function table.sum(input)
local tmp = 0
for i=1,#input do
  tmp = tmp+input[i]
end
return tmp
end

