    n('{|class="wikitable" style="text-align:center;width:100%"')
    n('|-')
    if sk[14+no][1] ~= sk[14+no][2] then -- 25~100数值有差异
      if equal({sk[14+no][2],sk[14+no][3],sk[14+no][4]}) then -- 0~50数值一致
