        n('|-')
        n('|HP25~50<br>'..sk[14+no][2]..'%释放')
        n('|-')
        n('|HP10~25<br>'..sk[14+no][3]..'%释放')
        n('|-')    
        n('|HP0~10<br>'..sk[14+no][4]..'%释放')
      n('|-')    
      end
    elseif sk[14+no][3] == sk[14+no][4] then -- 0~25、25~100数值一致
      n('|HP25~100<br>'..sk[14+no][1]..'%释放')
      n('|-')
      n('|HP0~25<br>'..sk[14+no][4]..'%释放')
