function n(input)
output = output..input.."\n"
end

function gauge_change_info(q1,q2,no_border)
  local elements={"日","月","火","水","木","金","土","星","无"}
  local tmp = {{},{},{},{}}
  for i=1,8 do -- 自动计算弱点耐性改变
    if string.sub(q1,i,i) == "0" then table.insert(tmp[1],elements[i]) end
    if string.sub(q1,i,i) == "2" then table.insert(tmp[2],elements[i]) end
    if string.sub(q2,i,i) == "0" then table.insert(tmp[3],elements[i]) end
    if string.sub(q2,i,i) == "2" then table.insert(tmp[4],elements[i]) end
  end
  -- print(tmp)
  local Output = ""
  if table.concat(tmp[1]) ~= table.concat(tmp[3]) then 
    if #tmp[3] == 0 then Output=Output.."\n自身<color=#CCAA00>弱点</color><color=#FF6600>消失</color> (永久)"
    elseif #tmp[3] == 1 then Output=Output.."\n自身<color=#CCAA00>弱点</color><color=#FF6600>变为</color>仅"..tmp[3][1].."属性 (永久)"
    else Output=Output.."\n自身<color=#CCAA00>弱点</color><color=#FF6600>变为</color>"..table.concat(tmp[3],"&").."属性 (永久)" end
  end
  if table.concat(tmp[2]) ~= table.concat(tmp[4]) then 
    if #tmp[4] == 0 then Output=Output.."\n自身<color=#CCAA00>耐性</color><color=#FF6600>消失</color> (永久)"
    elseif #tmp[4] == 1 then Output=Output.."\n自身<color=#CCAA00>耐性</color><color=#FF6600>变为</color>仅"..tmp[4][1].."属性 (永久)"
    else Output=Output.."\n自身<color=#CCAA00>耐性</color><color=#FF6600>变为</color>"..table.concat(tmp[4],"&").."属性 (永久)" end
  end
  if no_border == 1 then Output=Output.."\n自身<color=#0066FF>不会进入</color><color=#CCAA00>完全击破状态</color> (永久)\n自身<color=#0066FF>不会被附加</color><color=#CCAA00>结界异常</color> (永久)" end
  return Output
end

