function adv_color(n1,n2)
-- print(n1,n2)
if n1 > n2*1.5 then return "00AA00>\'\'\'"
elseif n1 > n2*1.1 then return "00AA00>"
-- elseif n1*1.5 < n2 then return "AA0000>\'\'\'"
-- elseif n1*1.1 < n2 then return "AA0000>"
else return "000000>" end
end

function ban_t(mode)
local tmp = ""
if mode == 1 then
  for i=1,9 do
    if ban[1][i] ~= nil then tmp = tmp..'[[File:属性 '..ban[1][i]..'.png|50px]]' end
  end
end
if mode == 5 then
  for i=1,5 do
    if ban[5][i] ~= nil then tmp = tmp..'[[File:结界 '..ban[5][i]..'.png|50px]]' end
  end
end
if mode == 2 then
  for i=1,11 do
    if ban[2][i] ~= nil then tmp = tmp..'[[File:Bullet Type Icon '..string.format("%02d",i)..'.png|50px]]' end
  end
end
if mode == 3 then
  sum = table.sum(ban[3])
  tmp = {}
  for i=1,8 do
    if ban[3][i] > 0 then table.insert(tmp,'[[File:属性 '..elements[i]..'.png|50px]]<br><font color=#'..adv_color(ban[3][i],ban[4][i])..""..ban[3][i]*100/sum.. '%</font>') end
  end
  return table.concat(tmp,"||")
end
if mode == 4 then
  sum = table.sum(ban[4])
  tmp = {}
  for i=1,8 do
    if ban[4][i] > 0 then table.insert(tmp,'[[File:属性 '..elements[i]..'.png|50px]]<br>'.. ban[4][i]*100/sum.. '%') end
  end
  return table.concat(tmp,"||")
end
if tmp == "" then tmp = "无" end
return tmp
end

