function create_json(input,n)
path = ""
if n == nil then n="" end
io.open("VS复灵wiki"..n..".json","w"):write("{")
for i=1,#st do
  file = io.open(path.."复灵"..st[i][1]..".txt","r")
  output = file:read("a")
  output = string.gsub(output,"\n","\\n")
  output = string.gsub(output,"\"","\\\"")
  -- output = string.gsub(output,".*\nWG\n","")
  link = "VS复灵"..st[i][1]
  link = string.gsub(link,"%]","］")
  io.open("VS复灵wiki"..n..".json","a"):write('"'..link..'":{"1":"'..output..'"}')
  print('|- <!-- 第'..i..'行 -->')
  print('||[[File:S'..st[i][12]..'.png|50px|link='..link..']] {{板块|按钮|'..link..'|'..st[i][2]..'|颜色=cc0000}}')
  if st[i][10] > 100000 then
  print('||VS复灵祭绘马')
  else
  print('||[[File:PTS'..st[i][10]..'.png|50px|link=]]<br>[['..get_card(st[i][10])..']]')
  end
  if i < #st then
    io.open("VS复灵wiki"..n..".json","a"):write(",")
  end
end
io.open("VS复灵wiki"..n..".json","a"):write("}")
end
